def translate_ui(value, language='ar'):
    if language != 'en' or not isinstance(value,str):return value
    if value in TRANSLATIONS:return TRANSLATIONS[value]
    # Translate interface fragments inside HTML and dynamic labels only.
    for ar,en in sorted(TRANSLATIONS.items(),key=lambda pair:len(pair[0]),reverse=True):
        if ar in value:value=value.replace(ar,en)
    return value
